from lib import *
S = SS('u125')
R = J('u125'); a, b = R['stats_O0'], R['stats_O3']; i0, i3 = R['inl_O0'], R['inl_O3']; lv = R['levels']
steps = [
    step(f"同一个 sum(v: &[i32]) 的 LLVM IR(--emit=llvm-ir):opt-level=0 是 {a['行数']} 行,有 {a['alloca']} 个 alloca(局部变量都是栈槽),{a['load']} 次 load、{a['store']} 次 store,没有 phi、没有向量;opt-level=3 是 {b['行数']} 行,alloca 为 {b['alloca']}、store 为 {b['store']},出现 {b['phi']} 个 phi(值直接放寄存器)和 {b['向量类型 <4 x i32>']} 处 <4 x i32> 向量类型 —— 循环被向量化了。", t=tl(S(1)), done=lidx(S(1), 'O0:', 'O3:'), b=bars([['O0 alloca', a['alloca'], str(a['alloca'])], ['O3 alloca', b['alloca'], str(b['alloca'])], ['O3 phi', b['phi'], str(b['phi'])], ['O3 <4 x i32>', b['向量类型 <4 x i32>'], str(b['向量类型 <4 x i32>'])]], max(b['向量类型 <4 x i32>'], 4), done=[0, 1, 2, 3]), kv=KV([['O0', f"alloca {a['alloca']} / phi {a['phi']} / 向量 {a['向量类型 <4 x i32>']}"], ['O3', f"alloca {b['alloca']} / phi {b['phi']} / 向量 {b['向量类型 <4 x i32>']}"]], ['O3'])),
    step("O0 的 sum 函数 IR 开头:%s = alloca [4 x i8],store i32 0, ptr %s;紧接着 call IntoIterator::into_iter 创建迭代器,循环里 call Iterator::next 取下一个元素 —— 在 O0 下这些标准库函数都没有内联,就是真实的函数调用;每个中间值先 store 再 load。", t=tl(S(2)), done=lidx(S(2), 'alloca', 'call'), kv=KV([['O0', 'alloca + store/load + 真调用 into_iter / next']], ['O0'])),
    step(f"内联:caller(a, b) = helper(a) + helper(b),helper 再调用 #[inline] 的 square_inline。O0 的 caller IR {i0[0]} 行,有 {len(i0[1])} 条 call 指令:{i0[1]}(helper 被真实调用两次,加法溢出检查还调用了 llvm.sadd.with.overflow 与 panic_const_add_overflow);O3 的 caller 只有 {i3[0]} 行、{len(i3[1])} 条 call —— helper 与 square_inline 全部被内联展开了。", t=tl(S(3)), done=lidx(S(3), 'O3:'), mark=lidx(S(3), 'O0:'), kv=KV([['O0 caller', f'{i0[0]} 行,{len(i0[1])} 条 call'], ['O3 caller', f'{i3[0]} 行,0 条 call']], ['O3 caller'])),
    step(f"同一个小库在不同 opt-level 下的汇编指令数:0 → {lv['0']} 条;1 → {lv['1']};2 → {lv['2']};3 → {lv['3']};s → {lv['s']};z → {lv['z']}。注意 2 和 3 比 1 还大 —— 向量化、循环展开用更多指令换速度;s、z 优先小体积。「优化」不等于「代码更短」。", t=tl(S(4)), done=lidx(S(4), 'opt-level='), b=bars([[f'opt-level={k}', v, f'{v} 条'] for k, v in lv.items()], max(lv.values()), done=list(range(len(lv)))), kv=KV([[f'opt-level={k}', f'{v} 条'] for k, v in lv.items()], ['opt-level=2'])),
]
A = mkart('u125', 125, 'Rust,LLVM,IR,优化,内联,真实验证,动画演示',
    f'用 --emit=llvm-ir 对比 O0 与 O3:sum 函数从 {a["行数"]} 行(alloca {a["alloca"]}、无向量)变成 {b["行数"]} 行({b["phi"]} 个 phi、{b["向量类型 <4 x i32>"]} 处 <4 x i32> 向量);O0 的 into_iter/next 是真实调用;caller 的 call 从 {len(i0[1])} 条到 0 条(内联);各 opt-level 汇编指令数 {lv["0"]}/{lv["1"]}/{lv["2"]}/{lv["3"]}/{lv["s"]}/{lv["z"]}。',
    'Rust 的性能很大程度上来自 LLVM 的优化。这篇用 LLVM IR 把「优化」变成看得见的东西:栈槽怎么变成寄存器、循环怎么被向量化、函数调用怎么被内联,以及为什么 -O3 的代码并不一定最短。',
    [(f'{a["alloca"]} → {b["alloca"]}', 'sum 函数 IR 里 alloca 的数量(O0 → O3)'), (f'{len(i0[1])} → 0', 'caller 里 call 指令的数量(O0 → O3,内联的结果)'), (f'{lv["1"]} 对 {lv["2"]}', 'opt-level=1 与 2 的汇编指令数(2 更大:向量化)')],
    [('O0 与 O3 的 IR', '<p>MIR 是 LLVM IR 的前一层,见<a href="rust-mir.html">MIR 是什么</a>。</p>'), ('O0 的 IR 长什么样', None), ('内联', '<p>单态化生成的代码见<a href="rust-monomorphization-codegen.html">Monomorphization 生成的代码</a>。</p>'), ('优化级别与体积', '<p>LTO 对体积的影响见<a href="rust-lto-binary-size.html">LTO 与二进制体积</a>。指令数来自 aarch64 汇编,x86_64 会不同。</p>')],
    steps, [ENV_U + '。IR 来自 --emit=llvm-ir,debuginfo=0', '没有验证:LLVM pass 的具体顺序(-print-pipeline-passes)、-C remark 的优化备注(在本机没有输出)、PGO 与 LTO 对内联决策的影响、x86_64 上的向量宽度(这里是 aarch64 的 NEON <4 x i32>)'], 'LLVM IR 与优化')
